// DATA:findings
const findings = [
  {
    "id": "marrow-and-liver",
    "title": "More marrow activity can mean more liver activity",
    "text": "Kim's mouse study counted cells making a protein after RNA delivery. One recipe had about 2.4 times the marrow response of another leading recipe, alongside 13 times the liver response.",
    "meaning": "Choosing a recipe means weighing both results. The highest marrow number alone does not tell you how well delivery stays in the cells you want to reach.",
    "evidence": [
      "LNP67: 20.9% of the tested marrow cells and 20.1% of the tested liver cells produced the marker protein. LNP108: 8.8% and 1.6%, respectively.",
      "Both were measured in the same mouse experiment at 0.5 mg/kg. The test counted early blood cells in marrow and cells lining blood vessels in the liver. These are percentages of cells, not percentages of the injected dose; a liver response is not itself evidence of liver damage."
    ],
    "sources": [
      "kim_2024"
    ]
  },
  {
    "id": "rna-at-work",
    "title": "RNA can work inside blood stem cells",
    "text": "Hofstraat's mouse experiments delivered RNA designed to lower a specific protein in blood stem cells. The strongest result was a reduction of about 58% after four injections.",
    "meaning": "Reaching a cell is only the first step. Measuring the intended protein change checks whether the RNA did its job inside the cell. That is useful evidence of delivery, although it does not establish a treatment benefit.",
    "evidence": [
      "Across 9 records, the measured reduction in a protein called LAMP1 ranged from 5.7% to 57.6% in long-term blood stem cells (LT-HSCs). These values compare the protein signal with a matched control; they do not mean that this percentage of cells was edited.",
      "The highest result was aNP8-siLAMP1. Dosing: 4 IV doses of 0.5 mg/kg siRNA at 36 h intervals (cumulative 2 mg/kg). Source: Figure 3 and its underlying data."
    ],
    "sources": [
      "hofstraat_2025"
    ]
  },
  {
    "id": "coating-comparison",
    "title": "The outer coating is worth a closer look",
    "text": "In Kim's mouse screen, recipes with different particle coatings gave very different marrow signals. Several ingredients varied together, so the data cannot tell us whether changing the coating alone would improve delivery.",
    "meaning": "This gives a useful starting point for the next comparison: change the coating while keeping the rest of the recipe and the dose the same. The current averages are a clue to investigate.",
    "evidence": [
      "PEG is part of the particle's outer coating. Among the recipes using the same helper ingredient, DOTAP, ALC-0159 had the highest mean marrow tracking signal (18.83; 3 records), compared with 0.33 for C18PEG2000 (4 records).",
      "The signal comes from DNA tags used to track the particles (normalized barcode counts). It measures a different outcome from gene editing or protein reduction. These small groups do not establish that one coating is better in other recipes."
    ],
    "sources": [
      "kim_2024"
    ]
  },
  {
    "id": "comparing-studies",
    "title": "More records do not yet give us a clear winner",
    "text": "The newer records mix different tests: some measure gene changes, others a protein decrease or light produced in marrow. A bigger score in one test does not mean a recipe would perform better in another.",
    "meaning": "Start with the test that matches your goal. To also judge how well delivery avoids the liver, we need marrow and liver measurements from the same experiment. Those matching liver numbers are still missing from the newer records.",
    "evidence": [
      "Xu 2026 measures gene editing; Hofstraat 2025 measures a reduction in a chosen protein; Hanafy 2025 measures light from a protein made after RNA delivery. These results describe different steps and cannot be combined into a single performance score.",
      "Of 196 added literature records, 0 currently have both numeric marrow and liver percentages from the same experiment. This is a gap in the collected records, not a claim that the original studies never measured the liver."
    ],
    "sources": [
      "xu_2026",
      "hofstraat_2025",
      "hanafy_2025"
    ]
  }
];
// END:findings

